211	    /**
212	     * The owner's numeric membership level, derived on creation: it starts at 1, gains 1 when an
213	     * email is present, gains 1 when {@link #namesakeCount} is 0, and is capped at 3 (level 4 is
214	     * reserved for tenure).
215	     */
216	    @Transient
217	    public Integer getMembershipLevel() {
218	        int level = 1;
219	        if (this.email != null && !this.email.isBlank()) {
220	            level++;
221	        }
222	        if (this.namesakeCount != null && this.namesakeCount == 0) {
223	            level++;
224	        }
225	        return Math.min(level, 3);
226	    }
227	
228	    /**
229	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
230	     * present, otherwise {@code "PHONE"}.
231	     */
232	    @Transient
233	    public String getContactPreference() {
234	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
235	    }
236	
237	    /**
238	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
239	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
240	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
241	     * date to measure against) is available.
242	     */
243	    @Transient
244	    public String getAgeBand() {
245	        if (this.birthDate == null || this.registrationDate == null) {
246	            return null;
247	        }
248	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
249	        if (age < 18) {
250	            return "MINOR";
251	        }
252	        if (age < 65) {
253	            return "ADULT";
254	        }
255	        return "SENIOR";
256	    }
257	
258	    /**
259	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
260	     * {@link #customerCode}, derived on read.
261	     */
262	    @Transient
263	    public Integer getCheckDigit() {
264	        return luhnCheckDigit(this.customerCode);
265	    }
266	
267	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
268	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
269	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
270	        "NSW", new int[] {2000, 2099},
271	        "VIC", new int[] {3000, 3099},
272	        "QLD", new int[] {4000, 4099});
273	
274	    /**
275	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
276	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
277	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
278	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
279	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
280	     */
281	    @Transient
282	    public String getRegion() {
283	        String byPostcode = regionForPostcode(this.postcode);
284	        if (byPostcode != null) {
285	            return byPostcode;
286	        }
287	        if ("Sydney".equals(this.city)) {
288	            return "NSW";
289	        }
290	        if ("Melbourne".equals(this.city)) {
291	            return "VIC";
292	        }
293	        if ("Brisbane".equals(this.city)) {
294	            return "QLD";
295	        }
296	        return "UNKNOWN";
297	    }
298	
299	    /**
300	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
301	     * customer code}: the region segment before the first '-' of the customer code
302	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
303	     * code has been assigned yet.
304	     */
305	    @Transient
306	    public String getLocality() {
307	        if (this.customerCode != null) {
308	            int dash = this.customerCode.indexOf('-');
309	            if (dash > 0) {
310	                return this.customerCode.substring(0, dash);
311	            }
312	        }
313	        return getRegion();
314	    }
315	
316	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
317	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
318	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
319	    public static int[] postcodeRangeForRegion(String region) {
320	        return REGION_POSTCODE_RANGES.get(region);
321	    }
322	
323	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
324	     *  absent, not a 4-digit value, or in no known range. */
325	    private static String regionForPostcode(String postcode) {
326	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
327	            return null;
328	        }
329	        int value = Integer.parseInt(postcode);
330	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
331	            int[] range = entry.getValue();
332	            if (value >= range[0] && value <= range[1]) {
333	                return entry.getKey();
334	            }
335	        }
336	        return null;
337	    }
338	
339	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
340	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
341	     *  digit-free value yields {@code 0}. */
342	    private static int luhnCheckDigit(String value) {
343	        int sum = 0;
344	        boolean doubling = true;
345	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
346	            char c = value.charAt(i);
347	            if (c < '0' || c > '9') {
348	                continue;
349	            }
350	            int digit = c - '0';
351	            if (doubling) {
352	                digit *= 2;
353	                if (digit > 9) {
354	                    digit -= 9;
355	                }
356	            }
357	            sum += digit;
358	            doubling = !doubling;
359	        }
360	        return (10 - (sum % 10)) % 10;
361	    }
362	
363	    protected Set<Pet> getPetsInternal() {
364	        if (this.pets == null) {
365	            this.pets = new HashSet<>();
366	        }
367	        return this.pets;
368	    }
369	
370	    protected void setPetsInternal(Set<Pet> pets) {
371	        this.pets = pets;
372	    }
373	
374	    public List<Pet> getPets() {
375	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
376	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
377	        return Collections.unmodifiableList(sortedPets);
378	    }
379	
380	    public void setPets(List<Pet> pets) {
381	        this.pets = new HashSet<>(pets);
382	    }
383	
384	    public void addPet(Pet pet) {
385	        getPetsInternal().add(pet);
386	        pet.setOwner(this);
387	    }
388	
389	    /**
390	     * Return the Pet with the given name, or null if none found for this Owner.
391	     *
392	     * @param name to test
393	     * @return true if pet name is already in use
394	     */
395	    public Pet getPet(String name) {
396	        return getPet(name, false);
397	    }
398	
399	    /**
400	     * Return the Pet with the given name, or null if none found for this Owner.
401	     *
402	     * @param name to test
403	     * @return true if pet name is already in use
404	     */
405	    public Pet getPet(String name, boolean ignoreNew) {
406	        name = name.toLowerCase();
407	        for (Pet pet : getPetsInternal()) {
408	            if (!ignoreNew || !pet.isNew()) {
409	                String compName = pet.getName();
410	                compName = compName.toLowerCase();
411	                if (compName.equals(name)) {
412	                    return pet;
413	                }
414	            }
415	        }
416	        return null;
417	    }
418	
419	    public Pet getPet(Integer petId) {
420	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
421	    }
422	
423	    @Override
424	    public String toString() {
425	        return new ToStringCreator(this)
426	
427	            .append("id", this.getId())
428	            .append("new", this.isNew())
429	            .append("lastName", this.getLastName())
430	            .append("firstName", this.getFirstName())
431	            .append("address", this.address)
432	            .append("city", this.city)
433	            .append("telephone", this.telephone)
434	            .toString();
435	    }
436	}
